import Handlebars from 'handlebars';
import empty from '../helper/funcs/empty.js';
import formatDate from '../helper/format/formatDate.js';

Handlebars.registerHelper('empty', empty);
Handlebars.registerHelper('formatDate', formatDate);

describe('empty helper', () => {

  // Тест для перевірки, чи повертається порожній рядок для будь-якого вхідного значення
  it('should return an empty string regardless of input', () => {
    const template = Handlebars.compile('{{empty "some input"}}');
    const result = template({});
    expect(result).toBe('');
  });

  // Тест для перевірки хелпера з об'єктом як аргумент
  it('should return an empty string when passing an object', () => {
    const template = Handlebars.compile('{{empty someObject}}');
    const result = template({ someObject: { key: 'value' } });
    expect(result).toBe('');
  });

  // Тест для перевірки хелпера з масивом як аргумент
  it('should return an empty string when passing an array', () => {
    const template = Handlebars.compile('{{empty someArray}}');
    const result = template({ someArray: [1, 2, 3] });
    expect(result).toBe('');
  });

  // Тест для перевірки хелпера з числом як аргумент
  it('should return an empty string when passing a number', () => {
    const template = Handlebars.compile('{{empty 123}}');
    const result = template({});
    expect(result).toBe('');
  });

  // Тест для перевірки хелпера з іншими хелперами всередині
  it('should return an empty string when passing another helper', () => {
    const template = Handlebars.compile('{{empty (formatDate someDate format="dd.MM.yy")}}');
    const result = template({ someDate: '2023-09-26T12:34:56' });
    expect(result).toBe('');
  });
  
  // Тест для перевірки хелпера без аргументів
  it('should return an empty string when no arguments are passed', () => {
    const template = Handlebars.compile('{{empty}}');
    const result = template({});
    expect(result).toBe('');
  });
});
